/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
p=Path(\"Task.v\")
s=p.read_text()
for abbrev,tag in [('typ','t'),('castop','c'),('exp','e')]:
 s=s.replace('''  induction a; intros k d x Hkd H; simpl in H;
    try solve [inversion H; subst; constructor; eauto with arith].
  destruct (lt_eq_lt_dec n k) as [[Hlt | Heq] | Hgt];
    inversion H; subst; constructor; lia.''', f'''  induction a; intros k d x Hkd H; simpl in H;
    try match goal with
    | |- _ _ ({tag}_var_b ?i) =>
        destruct (lt_eq_lt_dec i k) as [[Hlt | Heq] | Hgt]
    end;
    inversion H; subst; constructor; try lia;
    first [eapply IHa; [lia | eassumption] | eauto].''',1)
p.write_text(s)
PY
rocq compile -time -R . '' -R .rocq-deps/Metalib Metalib Task.v > /tmp/206-build.log 2>&1"

